package thaumcraft.utility;
import java.util.*;
import com.mojang.serialization.*;
import com.mojang.serialization.codecs.RecordCodecBuilder;
import net.minecraft.core.*;
import net.minecraft.nbt.*;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.entity.animal.Animal;
import net.minecraft.world.level.block.*;
import net.minecraft.world.level.ClipContext;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.level.storage.*;
import net.minecraft.world.phys.*;
import thaumcraft.essentia.*;
public final class LampEntity extends thaumcraft.devices.AuraDeviceEntity implements EssentiaTransport {
 public record State(int version,String identity,int charges,boolean reserve,int cursor,List<BlockPos> lights){}
 public static final Codec<State> CODEC=RecordCodecBuilder.create(i->i.group(Codec.intRange(1,1).fieldOf("version").forGetter(State::version),Codec.string(36,36).fieldOf("identity").forGetter(State::identity),Codec.intRange(0,20).fieldOf("charges").forGetter(State::charges),Codec.BOOL.fieldOf("reserve").forGetter(State::reserve),Codec.intRange(0,168).fieldOf("cursor").forGetter(State::cursor),BlockPos.CODEC.listOf(0,2048).fieldOf("lights").forGetter(State::lights)).apply(i,State::new));
 private String identity=UUID.randomUUID().toString();private int charges,ticks,cursor;private boolean reserve;private Tag unknown;private final List<BlockPos> lights=new ArrayList<>();
 public LampEntity(BlockPos p,BlockState s){super(UtilityContent.LAMPS.get(),p,s);}public boolean supported(){return unknown==null;}public int charges(){return charges;}public boolean reserve(){return reserve;}public String identity(){return identity;}public String kind(){return ((UtilityBlock)getBlockState().getBlock()).kind;}public Direction inlet(){return getBlockState().getValue(UtilityBlock.FACING);}public boolean running(){return supported()&&!isRemoved()&&level!=null&&!level.hasNeighborSignal(worldPosition);}
 private void lit(boolean on){if(getBlockState().getValue(UtilityBlock.ACTIVE)!=on)level.setBlockAndUpdate(worldPosition,getBlockState().setValue(UtilityBlock.ACTIVE,on));}
 public void serverTick(){if(!(level instanceof ServerLevel l)||!supported()||isRemoved())return;ticks++;if(kind().equals("lamp_arcane")){boolean on=running();lit(on);if(!on){clearLights();return;}if(ticks%100==0&&lights.removeIf(p->l.hasChunkAt(p)&&!(l.getBlockEntity(p) instanceof GlimmerEntity glow&&glow.belongs(worldPosition,identity))))setChanged();if(ticks%5==0){var p=worldPosition.offset(l.getRandom().nextInt(16)-l.getRandom().nextInt(16),l.getRandom().nextInt(16)-l.getRandom().nextInt(16),l.getRandom().nextInt(16)-l.getRandom().nextInt(16));illuminate(p);}return;}
  if(kind().equals("lamp_growth")&&charges==0&&reserve){charges=20;reserve=false;sync();}
  if(ticks%5==0&&suction(inlet())>0)EssentiaNetwork.pull(l,worldPosition,this,inlet());
  boolean active=running()&&charges>=(kind().equals("lamp_fertility")?5:1);lit(active);if(!active)return;
  if(kind().equals("lamp_growth"))growColumn();else if(ticks%300==0)breed();
 }
 public static boolean visible(ServerLevel l,BlockPos from,BlockPos to){var a=Vec3.atCenterOf(from);var b=Vec3.atCenterOf(to);int steps=(int)Math.ceil(a.distanceTo(b)*2);for(int n=0;n<=steps;n++){var p=BlockPos.containing(a.lerp(b,n/(double)Math.max(1,steps)));if(!l.hasChunkAt(p))return false;}return l.clip(new ClipContext(a,b,ClipContext.Block.COLLIDER,ClipContext.Fluid.NONE,net.minecraft.world.phys.shapes.CollisionContext.empty()){public net.minecraft.world.phys.shapes.VoxelShape getBlockShape(BlockState state,net.minecraft.world.level.BlockGetter world,BlockPos pos){return pos.equals(from)?net.minecraft.world.phys.shapes.Shapes.empty():super.getBlockShape(state,world,pos);}}).getType()==HitResult.Type.MISS;}
 public boolean illuminate(BlockPos p){if(!(level instanceof ServerLevel l)||!running()||!kind().equals("lamp_arcane")||lights.size()>=2048||Math.abs(p.getX()-worldPosition.getX())>15||Math.abs(p.getY()-worldPosition.getY())>15||Math.abs(p.getZ()-worldPosition.getZ())>15||!l.isInWorldBounds(p)||!l.hasChunkAt(p)||!l.isEmptyBlock(p)||l.getBrightness(net.minecraft.world.level.LightLayer.BLOCK,p)>=11||!visible(l,worldPosition,p))return false;if(!l.setBlockAndUpdate(p,UtilityContent.GLIMMER.get().defaultBlockState()))return false;if(l.getBlockEntity(p) instanceof GlimmerEntity glow){glow.bind(worldPosition,identity);lights.add(p.immutable());setChanged();return true;}l.removeBlock(p,false);return false;}
 private void clearLights(){if(!(level instanceof ServerLevel l))return;for(var p:lights)if(l.hasChunkAt(p)&&l.getBlockEntity(p) instanceof GlimmerEntity glow&&glow.belongs(worldPosition,identity))l.removeBlock(p,false);if(!lights.isEmpty()){lights.clear();setChanged();}}
 private void growColumn(){int n=cursor;cursor=(cursor+1)%169;setChanged();for(int y=6;y>=-6;y--){var p=worldPosition.offset(n/13-6,y,n%13-6);if(p.distSqr(worldPosition)>=36||!level.hasChunkAt(p))continue;var s=level.getBlockState(p);boolean plant=s.getBlock() instanceof BonemealableBlock grow&&grow.isValidBonemealTarget(level,p,s,BonemealSource.INTERACTION)||s.getBlock() instanceof CactusBlock||s.getBlock() instanceof SugarCaneBlock;if(!plant||!s.isRandomlyTicking()||s.is(net.minecraft.tags.BlockTags.DIRT))continue;charges--;s.randomTick((ServerLevel)level,p,level.getRandom());((ServerLevel)level).sendParticles(net.minecraft.core.particles.ParticleTypes.HAPPY_VILLAGER,p.getX()+.5,p.getY()+.5,p.getZ()+.5,3,.3,.3,.3,.01);sync();return;}}
 public boolean breed(){if(!(level instanceof ServerLevel l)||!running()||charges<5)return false;var animals=l.getEntitiesOfClass(Animal.class,new AABB(worldPosition).inflate(7),a->a.isAlive());for(var a:animals){if(!a.canFallInLove())continue;var family=animals.stream().filter(b->b.getType()==a.getType()).toList();if(family.size()>9)continue;var pair=family.stream().filter(Animal::canFallInLove).limit(2).toList();if(pair.size()!=2)continue;pair.get(0).setInLove(null);pair.get(1).setInLove(null);charges-=5;sync();return true;}return false;}
 public boolean connects(Direction face){return supported()&&!kind().equals("lamp_arcane")&&face==inlet();}public boolean canInput(Direction face){return connects(face);}public boolean canOutput(Direction face){return false;}public Map<String,Integer> contents(Direction face){return Map.of();}public String suctionType(Direction face){return kind().equals("lamp_growth")?"herba":"desiderium";}public int suction(Direction face){if(!connects(face))return 0;return kind().equals("lamp_growth")?(!reserve||charges==0?128:0):charges<10?128-charges*10:0;}public int minimumSuction(){return 0;}
 public boolean insert(String aspect,Direction face,boolean simulate){if(!canInput(face)||!aspect.equals(suctionType(face))||suction(face)==0)return false;if(!simulate){if(kind().equals("lamp_growth")){if(charges==0)charges=20;else reserve=true;}else charges++;sync();}return true;}public boolean extract(String a,Direction f,boolean s){return false;}
 public void preRemoveSideEffects(BlockPos p,BlockState s){super.preRemoveSideEffects(p,s);clearLights();}
 protected void saveAdditional(ValueOutput out){super.saveAdditional(out);if(unknown!=null)out.store("utility",Codec.PASSTHROUGH,new Dynamic<>(NbtOps.INSTANCE,unknown));else out.store("utility",CODEC,new State(1,identity,charges,reserve,cursor,List.copyOf(lights)));}
 protected void loadAdditional(ValueInput in){super.loadAdditional(in);unknown=null;charges=0;reserve=false;cursor=0;lights.clear();var raw=in.read("utility",Codec.PASSTHROUGH);if(raw.isPresent()){var state=CODEC.parse(raw.get()).result();if(state.isEmpty())unknown=raw.get().convert(NbtOps.INSTANCE).getValue().copy();else {var s=state.get();identity=s.identity();charges=s.charges();reserve=s.reserve();cursor=s.cursor();lights.addAll(s.lights());if(kind().equals("lamp_fertility")&&charges>10)unknown=raw.get().convert(NbtOps.INSTANCE).getValue().copy();}}}
}
